import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        # Store balances in integer cents internally to avoid floating-point drift
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._balances:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            actual_participants = list(self.members)
        else:
            actual_participants = list(participants)

        if not actual_participants:
            raise ValueError("Participants list cannot be empty.")

        for p in actual_participants:
            if p not in self._balances:
                raise ValueError(f"Participant '{p}' is not a group member.")

        # Convert total amount to integer cents
        total_cents = round(amount * 100)
        n = len(actual_participants)

        # Base share in cents rounded down to the nearest cent
        base_share_cents = total_cents // n

        # Apply cost to each participant and credit payer
        for p in actual_participants:
            if p == payer:
                # Payer's share absorbs the leftover cents
                leftover_cents = total_cents - base_share_cents * (n - 1)
                self._balances[payer] -= leftover_cents
            else:
                self._balances[p] -= base_share_cents

        self._balances[payer] += total_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: round(self._balances[m] / 100.0, 2) for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors (balance < 0) and Creditors (balance > 0)
        debtors = []
        creditors = []

        for m in self.members:
            bal = self._balances[m]
            if bal < 0:
                debtors.append([m, -bal])  # store debt as positive integer cents
            elif bal > 0:
                creditors.append([m, bal])

        payments = []
        d_idx = 0
        c_idx = 0

        # Greedy settlement guarantees at most (len(members) - 1) payments
        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_cents = debtors[d_idx]
            creditor, c_cents = creditors[c_idx]

            transfer_cents = min(d_cents, c_cents)

            if transfer_cents >= 100:
                payments.append((debtor, creditor, transfer_cents / 100.0))

            debtors[d_idx][1] -= transfer_cents
            creditors[c_idx][1] -= transfer_cents

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
```

